import 'dart:async';
import 'dart:convert';
import 'dart:math' as math;

import 'package:flutter/foundation.dart';

import 'models.dart';
import 'storage.dart';

const String _uncatId = 'uncat';
const int _uncatColor = 0xFF7C8698;

const List<int> _palette = <int>[
  0xFFD9A05B,
  0xFF6F9DF0,
  0xFF72C39A,
  0xFF5FC2C9,
  0xFFB489E6,
  0xFFE08AA0,
  0xFF6270C9,
  0xFFE3B341,
  0xFF7BD88F,
  0xFFFF8FAB,
  0xFFA78BFA,
  0xFFF0876A,
];

/// Bumped whenever the built-in sample changes. Data generated by an older
/// build can then be regenerated once, but only when it is still untouched
/// sample data (see [_isLegacySampleData]).
const int _sampleDataVersion = 2;

const Map<String, ({String name, int color})> _sampleTracks =
    <String, ({String name, int color})>{
      'food': (name: 'Food', color: 0xFFD9A05B),
      'work': (name: 'Work', color: 0xFF6F9DF0),
      'personal': (name: 'Personal', color: 0xFF72C39A),
      'learning': (name: 'Learning', color: 0xFF5FC2C9),
      'health': (name: 'Health', color: 0xFFB489E6),
      'media': (name: 'Media', color: 0xFFE08AA0),
      'rest': (name: 'Rest', color: 0xFF6270C9),
    };

const Set<String> _sampleTitles = <String>{
  'Breakfast',
  'Lunch',
  'Dinner',
  'Digestion',
  'Deep work',
  'Admin',
  'Side project',
  'Walk',
  'Chores',
  'Reading',
  'Medication',
  'Wind down',
  'Sleep',
  'Dentist',
  'Call family',
};

class UndoState {
  UndoState({
    required this.tracks,
    required this.blocks,
    required this.templates,
    required this.trackOpen,
    required this.showNames,
    required this.locked,
    required this.uncategorizedSlot,
  });

  final List<Track> tracks;
  final List<Block> blocks;
  final List<Template> templates;
  final Map<String, bool> trackOpen;
  final bool showNames;
  final bool locked;
  final int uncategorizedSlot;
}

class UndoEntry {
  UndoEntry({required this.state, required this.label});

  final UndoState state;
  final String label;
}

class ImportResult {
  const ImportResult({required this.tracks, required this.blocks});

  final int tracks;
  final int blocks;
}

class TimelineStore extends ChangeNotifier {
  TimelineStore({TimelineStorage? storage}) : this._(storage);

  TimelineStore._(this._storage) {
    final DateTime now = DateTime.now();
    timelineStart = DateTime(now.year, now.month, now.day - 4);
    timelineEnd = DateTime(now.year, now.month, now.day + 4);
  }

  late final DateTime timelineStart;
  late final DateTime timelineEnd;

  final List<Track> tracks = <Track>[];
  final List<Block> blocks = <Block>[];
  final List<Template> templates = <Template>[];
  final Map<String, bool> trackOpen = <String, bool>{};
  final List<UndoEntry> undoStack = <UndoEntry>[];

  bool showNames = true;
  bool locked = false;

  /// Insertion position of the built-in Uncategorized category among the
  /// editable categories. -1 keeps it after the last category.
  int _uncategorizedSlot = -1;

  int _nextBlockId = 1;
  int _nextTrackId = 1;
  int _nextTemplateId = 1;
  int _sampleVersion = 0;
  Timer? _saveTimer;
  TimelineStorage? _storage;

  Map<int, _MoveOriginals>? _groupMoveOriginals;
  Map<int, int?> _fixedLanes = <int, int?>{};
  bool _groupMoveVertical = false;

  bool get hasUndo => undoStack.isNotEmpty;
  int get maxUndo => 30;

  /// Categories in display order, including Uncategorized even when it is
  /// currently empty. This lets the Categories sheet move it at any time.
  List<Track> get displayTracks {
    if (tracks.any((Track track) => track.id == _uncatId)) {
      return List<Track>.of(tracks);
    }
    final List<Track> result = List<Track>.of(tracks);
    final int slot = _uncategorizedSlot < 0
        ? result.length
        : _uncategorizedSlot.clamp(0, result.length);
    result.insert(slot, uncategorized);
    return result;
  }

  Track? trackById(String id) {
    for (final Track track in tracks) {
      if (track.id == id) return track;
    }
    return null;
  }

  Track get uncategorized => Track(
    id: _uncatId,
    name: 'Uncategorized',
    colorValue: _uncatColor,
    fixed: true,
  );

  Track trackOrUncategorized(String id) => trackById(id) ?? uncategorized;

  bool hasBlocksInTrack(String trackId) =>
      blocks.any((Block block) => block.trackId == trackId);

  int blockCountForTrack(String trackId) =>
      blocks.where((Block block) => block.trackId == trackId).length;

  Block? blockById(int id) {
    for (final Block block in blocks) {
      if (block.id == id) return block;
    }
    return null;
  }

  Block? currentBlock(DateTime now) {
    final List<Block> current =
        blocks
            .where(
              (Block block) =>
                  !block.isZone &&
                  !now.isBefore(block.start) &&
                  now.isBefore(block.end),
            )
            .toList()
          ..sort((Block a, Block b) => a.end.compareTo(b.end));
    return current.isEmpty ? null : current.first;
  }

  List<Block> nextBlocks(DateTime now, {int limit = 3}) {
    final List<Block> upcoming =
        blocks
            .where((Block block) => !block.isZone && block.start.isAfter(now))
            .toList()
          ..sort((Block a, Block b) => a.start.compareTo(b.start));
    return upcoming.take(limit).toList(growable: false);
  }

  Future<void> load({TimelineStorage? storage}) async {
    _storage = storage ?? _storage ?? await createDefaultTimelineStorage();
    final String? raw = await _storage!.read();
    if (raw != null) {
      try {
        final Object? decoded = jsonDecode(raw);
        if (decoded is Map<String, dynamic> && _restoreFromMap(decoded)) {
          _scheduleSave();
          return;
        }
      } catch (_) {
        // A damaged preference bundle must never make the app unusable.
      }
    }
    _seedSampleData();
    _ensureUncategorized();
    _scheduleSave();
  }

  bool _restoreFromMap(Map<String, dynamic> map) {
    final Object? rawTracks = map['tracks'];
    final Object? rawBlocks = map['blocks'];
    if (rawTracks is! List || rawBlocks is! List) return false;

    final List<Track> restoredTracks = <Track>[];
    for (final Object? item in rawTracks) {
      if (item is! Map) continue;
      final Track track = Track.fromJson(Map<String, dynamic>.from(item));
      if (track.id.isEmpty ||
          track.id == _uncatId ||
          restoredTracks.any((Track t) => t.id == track.id)) {
        continue;
      }
      restoredTracks.add(track);
    }

    final Set<String> ids = restoredTracks
        .map((Track track) => track.id)
        .toSet();
    final List<Block> restoredBlocks = <Block>[];
    final Set<int> usedIds = <int>{};
    int nextId = 1;
    for (final Object? item in rawBlocks) {
      if (item is! Map) continue;
      try {
        final Map<String, dynamic> json = Map<String, dynamic>.from(item);
        int id = (json['id'] is num)
            ? (json['id'] as num).toInt()
            : int.tryParse('${json['id'] ?? ''}') ?? 0;
        if (id <= 0 || usedIds.contains(id)) {
          while (usedIds.contains(nextId)) {
            nextId++;
          }
          id = nextId;
        }
        usedIds.add(id);
        nextId = math.max(nextId, id + 1);
        final Block block = Block.fromJson(json, fallbackId: id);
        block.id = id;
        if (!ids.contains(block.trackId)) block.trackId = _uncatId;
        restoredBlocks.add(block);
      } catch (_) {
        // Skip malformed blocks instead of rejecting the whole file.
      }
    }

    final List<Template> restoredTemplates = <Template>[];
    final Object? rawTemplates = map['templates'];
    if (rawTemplates is List) {
      final Set<int> usedTemplateIds = <int>{};
      int nextTemplateId = 1;
      for (final Object? item in rawTemplates) {
        if (item is! Map) continue;
        try {
          final Map<String, dynamic> json = Map<String, dynamic>.from(item);
          int id = (json['id'] is num)
              ? (json['id'] as num).toInt()
              : int.tryParse('${json['id'] ?? ''}') ?? 0;
          if (id <= 0 || usedTemplateIds.contains(id)) {
            while (usedTemplateIds.contains(nextTemplateId)) {
              nextTemplateId++;
            }
            id = nextTemplateId;
          }
          usedTemplateIds.add(id);
          nextTemplateId = math.max(nextTemplateId, id + 1);
          restoredTemplates.add(Template.fromJson(json, fallbackId: id));
        } catch (_) {}
      }
      _nextTemplateId = nextTemplateId;
    }

    final int storedSample = map['sample'] is num
        ? (map['sample'] as num).toInt()
        : 0;
    if (storedSample < _sampleDataVersion &&
        _isLegacySampleData(
          restoredTracks,
          restoredBlocks,
          restoredTemplates,
        )) {
      // Untouched sample data from an older build. Let load() regenerate it
      // with the current layout instead of keeping stale overlapping blocks.
      return false;
    }
    _sampleVersion = math.max(storedSample, _sampleDataVersion);

    tracks
      ..clear()
      ..addAll(restoredTracks);
    blocks
      ..clear()
      ..addAll(restoredBlocks);
    templates
      ..clear()
      ..addAll(restoredTemplates);
    _nextBlockId = nextId;
    _nextTrackId = _nextAvailableTrackNumber();
    undoStack.clear();
    showNames = map['namesHidden'] != true;
    locked = map['locked'] == true;

    trackOpen.clear();
    final Object? rawOpen = map['trackOpen'];
    if (rawOpen is Map) {
      rawOpen.forEach((Object? key, Object? value) {
        if (key is String) trackOpen[key] = value != false;
      });
    }
    for (final Track track in tracks) {
      trackOpen.putIfAbsent(track.id, () => true);
    }
    _uncategorizedSlot = map['uncategorizedSlot'] is num
        ? (map['uncategorizedSlot'] as num).toInt()
        : -1;
    _ensureUncategorized();
    return true;
  }

  /// True when the saved data is still the built-in sample from Timeline 1.1
  /// or earlier. A single custom category, renamed category, custom title or
  /// non-sample template is enough to treat the data as the user's own.
  bool _isLegacySampleData(
    List<Track> restoredTracks,
    List<Block> restoredBlocks,
    List<Template> restoredTemplates,
  ) {
    if (restoredTracks.length != _sampleTracks.length) return false;
    for (final Track track in restoredTracks) {
      final ({String name, int color})? expected = _sampleTracks[track.id];
      if (expected == null ||
          expected.name != track.name ||
          expected.color != track.colorValue) {
        return false;
      }
    }
    if (restoredBlocks.isEmpty) return false;
    for (final Block block in restoredBlocks) {
      if (!_sampleTitles.contains(block.title)) return false;
      if (block.alarms.isNotEmpty || block.repeat.active) return false;
    }
    if (restoredTemplates.length > 3) return false;
    for (final Template template in restoredTemplates) {
      if (!_sampleTitles.contains(template.title)) return false;
    }
    return true;
  }

  int _nextAvailableTrackNumber() {
    int result = 1;
    for (final Track track in tracks) {
      final Match? match = RegExp(r'^cat-(\d+)$').firstMatch(track.id);
      if (match != null) {
        result = math.max(result, int.parse(match.group(1)!) + 1);
      }
    }
    return result;
  }

  void _ensureUncategorized() {
    final Set<String> known = tracks.map((Track track) => track.id).toSet();
    bool needsUncat = blocks.any(
      (Block block) => !known.contains(block.trackId),
    );
    needsUncat =
        needsUncat || blocks.any((Block block) => block.trackId == _uncatId);
    if (needsUncat) {
      if (!known.contains(_uncatId)) {
        final int slot = _uncategorizedSlot < 0
            ? tracks.length
            : _uncategorizedSlot.clamp(0, tracks.length);
        tracks.insert(slot, uncategorized);
        trackOpen[_uncatId] = true;
      }
      for (final Block block in blocks) {
        if (!known.contains(block.trackId)) block.trackId = _uncatId;
      }
    } else {
      final int index = tracks.indexWhere(
        (Track track) => track.id == _uncatId,
      );
      if (index >= 0) {
        _uncategorizedSlot = index;
        tracks.removeAt(index);
      }
      trackOpen.remove(_uncatId);
    }
    for (final Block block in blocks) {
      if (block.trackId == _uncatId &&
          !tracks.any((Track t) => t.id == _uncatId)) {
        // This can only happen if a caller changed the block list directly.
        // Keeping the invariant in one place avoids an invisible block.
        final int slot = _uncategorizedSlot < 0
            ? tracks.length
            : _uncategorizedSlot.clamp(0, tracks.length);
        tracks.insert(slot, uncategorized);
        trackOpen[_uncatId] = true;
      }
    }
    normalizeLanes();
  }

  UndoState captureState() => UndoState(
    tracks: tracks.map((Track track) => track.copyWith()).toList(),
    blocks: blocks
        .map(
          (Block block) =>
              block.copyWith(clearSeriesId: block.seriesId == null),
        )
        .toList(),
    templates: templates
        .map(
          (Template template) => Template(
            id: template.id,
            title: template.title,
            trackId: template.trackId,
            durationMinutes: template.durationMinutes,
            kind: template.kind,
            alarms: template.alarms,
            repeat: template.repeat,
            parts: List<TemplatePart>.of(template.parts),
          ),
        )
        .toList(),
    trackOpen: Map<String, bool>.from(trackOpen),
    showNames: showNames,
    locked: locked,
    uncategorizedSlot: _uncategorizedSlot,
  );

  void recordUndoState(UndoState state, String label) {
    undoStack.add(UndoEntry(state: state, label: label));
    if (undoStack.length > maxUndo) undoStack.removeAt(0);
    notifyListeners();
  }

  void _pushUndo(String label) => recordUndoState(captureState(), label);

  String? undo() {
    if (undoStack.isEmpty) return null;
    final UndoEntry entry = undoStack.removeLast();
    final UndoState state = entry.state;
    tracks
      ..clear()
      ..addAll(state.tracks.map((Track track) => track.copyWith()));
    blocks
      ..clear()
      ..addAll(
        state.blocks.map(
          (Block block) =>
              block.copyWith(clearSeriesId: block.seriesId == null),
        ),
      );
    templates
      ..clear()
      ..addAll(
        state.templates.map(
          (Template template) => Template(
            id: template.id,
            title: template.title,
            trackId: template.trackId,
            durationMinutes: template.durationMinutes,
            kind: template.kind,
            alarms: template.alarms,
            repeat: template.repeat,
            parts: List<TemplatePart>.of(template.parts),
          ),
        ),
      );
    trackOpen
      ..clear()
      ..addAll(state.trackOpen);
    showNames = state.showNames;
    locked = state.locked;
    _uncategorizedSlot = state.uncategorizedSlot;
    _nextBlockId = _maxBlockId() + 1;
    _nextTrackId = _nextAvailableTrackNumber();
    _nextTemplateId = _maxTemplateId() + 1;
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
    return entry.label;
  }

  int _maxBlockId() => blocks.fold<int>(
    0,
    (int value, Block block) => math.max(value, block.id),
  );

  int _maxTemplateId() => templates.fold<int>(
    0,
    (int value, Template template) => math.max(value, template.id),
  );

  void toggleTrackOpen(String trackId) {
    trackOpen[trackId] = trackOpen[trackId] == false;
    notifyListeners();
    _scheduleSave();
  }

  void toggleCollapseAll() {
    final bool anyOpen = tracks.any(
      (Track track) => trackOpen[track.id] != false,
    );
    for (final Track track in tracks) {
      trackOpen[track.id] = !anyOpen;
    }
    notifyListeners();
    _scheduleSave();
  }

  void toggleShowNames() {
    showNames = !showNames;
    notifyListeners();
    _scheduleSave();
  }

  void toggleLock() {
    locked = !locked;
    notifyListeners();
    _scheduleSave();
  }

  Track addTrack({String? name, int? colorValue}) {
    _pushUndo('Added category');
    final int index = _nextTrackId++;
    final Track track = Track(
      id: 'cat-$index',
      name: name?.trim().isNotEmpty == true ? name!.trim() : 'New category',
      colorValue: colorValue ?? _palette[(index - 1) % _palette.length],
    );
    final int uncatIndex = tracks.indexWhere(
      (Track item) => item.id == _uncatId,
    );
    if (uncatIndex == tracks.length - 1) {
      tracks.insert(uncatIndex, track);
    } else {
      if (_uncategorizedSlot >= 0 && _uncategorizedSlot >= tracks.length) {
        _uncategorizedSlot++;
      }
      tracks.add(track);
    }
    trackOpen[track.id] = true;
    notifyListeners();
    _scheduleSave();
    return track;
  }

  void reorderCategory(String trackId, int targetIndex) {
    final List<Track> display = displayTracks;
    final int oldIndex = display.indexWhere(
      (Track track) => track.id == trackId,
    );
    if (oldIndex < 0) return;
    final int target = targetIndex.clamp(0, display.length - 1);
    if (oldIndex == target) return;
    _pushUndo('Reordered categories');
    final Track moved = display.removeAt(oldIndex);
    display.insert(target, moved);
    final int uncatIndex = display.indexWhere(
      (Track track) => track.id == _uncatId,
    );
    _uncategorizedSlot = uncatIndex;
    tracks
      ..clear()
      ..addAll(display.where((Track track) => track.id != _uncatId));
    if (uncatIndex >= 0 && hasBlocksInTrack(_uncatId)) {
      tracks.insert(uncatIndex, uncategorized);
      trackOpen[_uncatId] = true;
    }
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
  }

  void clearTrack(String trackId) {
    final Track? track = trackById(trackId);
    if (track == null) return;
    final int count = blockCountForTrack(trackId);
    if (count == 0) return;
    _pushUndo('Cleared ${track.name}');
    blocks.removeWhere((Block block) => block.trackId == trackId);
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
  }

  bool renameTrack(String trackId, String name) {
    final Track? track = trackById(trackId);
    if (track == null || track.fixed) return false;
    final String cleaned = name.trim();
    final String next = cleaned.isEmpty ? 'Untitled' : cleaned;
    if (next == track.name) return false;
    _pushUndo('Renamed category');
    final Track updated = track.copyWith(name: next);
    final int index = tracks.indexWhere((Track item) => item.id == trackId);
    if (index >= 0) tracks[index] = updated;
    notifyListeners();
    _scheduleSave();
    return true;
  }

  void setTrackColor(String trackId, int colorValue) {
    final Track? track = trackById(trackId);
    if (track == null || track.fixed || track.colorValue == colorValue) return;
    _pushUndo('Changed category colour');
    final int index = tracks.indexWhere((Track item) => item.id == trackId);
    if (index >= 0) {
      tracks[index] = track.copyWith(colorValue: colorValue);
      notifyListeners();
      _scheduleSave();
    }
  }

  void deleteTrack(String trackId) {
    final Track? track = trackById(trackId);
    if (track == null || track.fixed) return;
    _pushUndo('Deleted category');
    tracks.removeWhere((Track item) => item.id == trackId);
    trackOpen.remove(trackId);
    for (final Block block in blocks) {
      if (block.trackId == trackId) block.trackId = _uncatId;
    }
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
  }

  Block? saveBlock(Block draft, {required bool isNew}) {
    final Block? existing = isNew ? null : blockById(draft.id);
    final Duration duration = draft.end.difference(draft.start);
    if (duration <= Duration.zero) return null;

    _pushUndo(isNew ? 'Added ${draft.title}' : 'Edited ${draft.title}');

    if (existing != null) {
      if (existing.seriesId != null) {
        blocks.removeWhere(
          (Block block) => block.seriesId == existing.seriesId,
        );
      } else {
        blocks.removeWhere((Block block) => block.id == existing.id);
      }
    }

    int primaryId = existing?.id ?? _nextBlockId++;
    if (isNew) {
      _nextBlockId = math.max(_nextBlockId, primaryId + 1);
    }
    draft.id = primaryId;

    // A repeat rule with nothing ticked is treated as "does not repeat" rather
    // than silently dropping every occurrence.
    if (!draft.repeat.active || !draft.repeat.isValid) {
      draft.repeat = RepeatSpec.none;
      draft.seriesId = null;
      final Block saved = draft.copyWith(
        id: primaryId,
        seriesId: null,
        clearSeriesId: true,
      );
      blocks.add(saved);
      _sortBlocks();
      _ensureUncategorized();
      notifyListeners();
      _scheduleSave();
      return saved;
    }

    final int? oldSeriesId = existing?.seriesId;
    final int seriesId = oldSeriesId ?? primaryId;
    draft.seriesId = seriesId;
    final List<Block> generated = _expandRecurringBlock(draft, seriesId);
    Block? primary;
    for (final Block block in generated) {
      blocks.add(block);
      if (block.start.isAtSameMomentAs(draft.start)) primary = block;
    }
    if (primary == null) {
      primary = draft.copyWith(seriesId: seriesId);
      blocks.add(primary);
    }
    _sortBlocks();
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
    return primary;
  }

  List<Block> _expandRecurringBlock(Block draft, int seriesId) {
    final RepeatSpec spec = draft.repeat;
    final List<DateTime> starts = <DateTime>[];
    final DateTime base = draft.start;
    final Duration duration = draft.duration;

    if (spec.isDaily) {
      final Set<int> days = spec.days.isEmpty ? <int>{base.weekday} : spec.days;
      for (int offset = -20; offset <= 20; offset++) {
        final DateTime candidate = addLocalDays(base, offset);
        if (!days.contains(candidate.weekday)) continue;
        _addIfVisible(starts, candidate, duration);
      }
    } else if (spec.isHourly) {
      final Set<int> hours = spec.hours.isEmpty ? <int>{base.hour} : spec.hours;
      final List<int> ordered = hours.toList(growable: false)..sort();
      DateTime day = addLocalDays(startOfLocalDay(timelineStart), -1);
      final DateTime lastDay = startOfLocalDay(timelineEnd);
      while (!day.isAfter(lastDay)) {
        for (final int hour in ordered) {
          final DateTime candidate = DateTime(
            day.year,
            day.month,
            day.day,
            hour,
            base.minute,
            base.second,
          );
          _addIfVisible(starts, candidate, duration);
        }
        day = addLocalDays(day, 1);
      }
    }

    if (!starts.any((DateTime start) => start.isAtSameMomentAs(base))) {
      starts.add(base);
    }
    starts.sort();
    final List<Block> result = <Block>[];
    for (final DateTime start in starts) {
      final bool isPrimary = start.isAtSameMomentAs(base);
      final int id = isPrimary ? draft.id : _nextBlockId++;
      result.add(
        draft.copyWith(
          id: id,
          start: start,
          end: start.add(duration),
          seriesId: seriesId,
          clearSeriesId: false,
        ),
      );
      _nextBlockId = math.max(_nextBlockId, id + 1);
    }
    return result;
  }

  void _addIfVisible(
    List<DateTime> starts,
    DateTime candidate,
    Duration duration,
  ) {
    if (candidate.add(duration).isAfter(timelineStart) &&
        candidate.isBefore(timelineEnd)) {
      starts.add(candidate);
    }
  }

  void _sortBlocks() {
    blocks.sort((Block a, Block b) {
      final int byStart = a.start.compareTo(b.start);
      if (byStart != 0) return byStart;
      return a.id.compareTo(b.id);
    });
  }

  /// Collapses empty lanes at the top of each category/shape stack so a track
  /// only grows as far as its contents. Gaps between events and the bottom
  /// edge (which is always the last occupied lane) are preserved.
  void normalizeLanes() {
    final Map<String, List<Block>> groups = <String, List<Block>>{};
    for (final Block block in blocks) {
      final String key = '${block.trackId}|${block.isZone}';
      groups.putIfAbsent(key, () => <Block>[]).add(block);
    }
    bool changed = false;
    for (final List<Block> group in groups.values) {
      final int first = group
          .map((Block block) => math.max(0, block.lane ?? 0))
          .reduce(math.min);
      if (first == 0) continue;
      for (final Block block in group) {
        final int lane = math.max(0, block.lane ?? 0);
        block.lane = math.max(0, lane - first);
        changed = true;
      }
    }
    if (changed) _scheduleSave();
  }

  void moveBlockLive(
    int blockId,
    DateTime start,
    DateTime end, {
    bool resize = false,
  }) {
    final Block? block = blockById(blockId);
    if (block == null) return;
    final DateTime oldStart = block.start;
    final Duration newDuration = end.difference(start);
    if (newDuration <= Duration.zero) return;

    if (block.seriesId == null) {
      block.start = start;
      block.end = end;
    } else {
      final int deltaMs = start.difference(oldStart).inMilliseconds;
      final List<({Block block, Duration duration})> series = blocks
          .where((Block item) => item.seriesId == block.seriesId)
          .map((Block item) => (block: item, duration: item.duration))
          .toList(growable: false);
      for (final ({Block block, Duration duration}) item in series) {
        item.block.start = item.block.start.add(
          Duration(milliseconds: deltaMs),
        );
        item.block.end = item.block.start.add(
          resize ? newDuration : item.duration,
        );
      }
    }
    notifyListeners();
  }

  /// Starts a rigid drag for one or more selected blocks. The optional lane
  /// map is the layout's current lane for visible blocks; it lets the store
  /// resolve collisions against blocks that have not been assigned an explicit
  /// lane yet.
  void beginGroupMove(
    Set<int> selectedIds, {
    Map<int, int> lanes = const <int, int>{},
    bool allowVertical = false,
  }) {
    final List<Block> selected = blocks
        .where((Block block) => selectedIds.contains(block.id))
        .toList(growable: false);
    if (selected.isEmpty) return;
    final Set<int> seriesIds = selected
        .map((Block block) => block.seriesId)
        .whereType<int>()
        .toSet();
    final Map<int, _MoveOriginals> originals = <int, _MoveOriginals>{};
    for (final Block block in blocks) {
      final bool inGroup =
          selectedIds.contains(block.id) ||
          (block.seriesId != null && seriesIds.contains(block.seriesId));
      if (!inGroup) continue;
      int lane = lanes[block.id] ?? block.lane ?? 0;
      if (!selectedIds.contains(block.id) && block.seriesId != null) {
        final Block? anchor = selected
            .where((Block item) => item.seriesId == block.seriesId)
            .firstOrNull;
        if (anchor != null) {
          lane = lanes[anchor.id] ?? anchor.lane ?? lane;
        }
      }
      originals[block.id] = _MoveOriginals(
        start: block.start,
        end: block.end,
        lane: math.max(0, lane),
      );
    }
    _groupMoveOriginals = originals;
    _fixedLanes = <int, int?>{
      for (final Block block in blocks)
        if (!originals.containsKey(block.id)) block.id: block.lane,
    };
    _groupMoveVertical = allowVertical;
  }

  void updateGroupMove({
    required int deltaMs,
    required int laneDelta,
    bool preferAbove = false,
  }) {
    final Map<int, _MoveOriginals>? originals = _groupMoveOriginals;
    if (originals == null || originals.isEmpty) return;
    final Set<int> affectedIds = originals.keys.toSet();
    final List<Block> affected = blocks
        .where((Block block) => affectedIds.contains(block.id))
        .toList(growable: false);
    if (affected.isEmpty) return;

    // Undo any blocks that were pushed aside by the previous frame before
    // recalculating the insertion.
    for (final MapEntry<int, int?> entry in _fixedLanes.entries) {
      final Block? block = blockById(entry.key);
      if (block != null) block.lane = entry.value;
    }

    final Map<int, Block> affectedById = <int, Block>{
      for (final Block block in affected) block.id: block,
    };
    final Map<int, DateTime> starts = <int, DateTime>{};
    final Map<int, DateTime> ends = <int, DateTime>{};
    final Map<int, int> requested = <int, int>{};
    final Map<String, List<int>> groups = <String, List<int>>{};
    for (final Block block in affected) {
      final _MoveOriginals origin = originals[block.id]!;
      starts[block.id] = origin.start.add(Duration(milliseconds: deltaMs));
      ends[block.id] = origin.end.add(Duration(milliseconds: deltaMs));
      requested[block.id] = origin.lane + (_groupMoveVertical ? laneDelta : 0);
      final String key = '${block.trackId}|${block.isZone}';
      groups.putIfAbsent(key, () => <int>[]).add(block.id);
    }

    final Map<String, int> shifts = <String, int>{};
    if (_groupMoveVertical) {
      for (final MapEntry<String, List<int>> entry in groups.entries) {
        final List<int> ids = entry.value;
        final Block sample = affectedById[ids.first]!;
        final List<Block> fixed = blocks
            .where(
              (Block block) =>
                  !affectedIds.contains(block.id) &&
                  block.trackId == sample.trackId &&
                  block.isZone == sample.isZone,
            )
            .toList(growable: false);

        // Preserve the selection's relative rows when the group hits lane 0.
        // Clamping each block separately would stack them all on the top row.
        final int rawMin = ids.map((int id) => requested[id]!).reduce(math.min);
        final int upwardOverflow = rawMin < 0 ? -rawMin : 0;
        int minLane = rawMin;
        if (minLane < 0) {
          for (final int id in ids) {
            requested[id] = requested[id]! - minLane;
          }
          minLane = 0;
        }
        final int maxLane = ids
            .map((int id) => requested[id]!)
            .reduce(math.max);

        // Upward dragging reaches a hard floor at lane 0. When the selection
        // is at or above the top occupied row, move the whole existing stack
        // down instead, so the user can keep inserting lines above it.
        if (preferAbove && laneDelta < 0 && fixed.isNotEmpty) {
          final int fixedTop = fixed
              .map((Block block) => block.lane ?? 0)
              .reduce(math.min);
          if (minLane <= fixedTop && maxLane >= fixedTop) {
            final int push = maxLane - fixedTop + 1 + upwardOverflow;
            for (final Block other in fixed) {
              other.lane = (other.lane ?? 0) + push;
            }
          }
        }

        bool collides(int extra) {
          for (final int id in ids) {
            final _MoveOriginals origin = originals[id]!;
            final int lane = requested[id]! + extra;
            if (lane < 0) return true;
            final DateTime start = starts[id]!;
            final DateTime end = ends[id]!;
            for (final Block other in fixed) {
              final int otherLane = other.lane ?? 0;
              if (otherLane != lane) continue;
              // Only a real visual overlap forces a row change. Non-overlapping
              // events can share a row, which keeps vertical drags predictable.
              if (!other.end.isAfter(start) || !other.start.isBefore(end)) {
                continue;
              }
              // Keep deliberate overlaps intact during a horizontal move.
              if (laneDelta == 0 &&
                  otherLane == origin.lane &&
                  other.end.isAfter(origin.start) &&
                  other.start.isBefore(origin.end)) {
                continue;
              }
              return true;
            }
          }
          return false;
        }

        if (!collides(0)) {
          shifts[entry.key] = 0;
          continue;
        }

        int shift = 0;
        bool placed = false;
        if (preferAbove) {
          for (int candidate = -1; candidate >= -minLane; candidate--) {
            if (!collides(candidate)) {
              shift = candidate;
              placed = true;
              break;
            }
          }
        }
        if (!placed && !preferAbove) {
          for (int candidate = 1; candidate < 200; candidate++) {
            if (!collides(candidate)) {
              shift = candidate;
              placed = true;
              break;
            }
          }
        }
        if (!placed && preferAbove) {
          // No free lane above: insert at the top and push the existing stack
          // down until the selected rows are clear.
          int guard = 0;
          while (collides(0) && guard < 200) {
            for (final Block other in fixed) {
              other.lane = (other.lane ?? 0) + 1;
            }
            guard++;
          }
        }
        shifts[entry.key] = shift;
      }
    }

    for (final Block block in affected) {
      block.start = starts[block.id]!;
      block.end = ends[block.id]!;
      final String key = '${block.trackId}|${block.isZone}';
      block.lane = math.max(0, requested[block.id]! + (shifts[key] ?? 0));
    }
    notifyListeners();
  }

  int groupLaneShiftFor(int blockId, int targetLane) {
    final Map<int, _MoveOriginals>? originals = _groupMoveOriginals;
    if (originals == null || !originals.containsKey(blockId)) return 0;
    final int current = originals[blockId]!.lane;
    return targetLane - current;
  }

  void finishLiveChange() {
    _groupMoveOriginals = null;
    _fixedLanes = <int, int?>{};
    _groupMoveVertical = false;
    // Boundary rows collapse on release; gaps the user created between events
    // stay exactly where they were.
    normalizeLanes();
    notifyListeners();
    _scheduleSave();
  }

  void deleteBlock(int blockId, {bool wholeSeries = false}) {
    final Block? block = blockById(blockId);
    if (block == null) return;
    _pushUndo('Deleted ${block.title}');
    if (wholeSeries && block.seriesId != null) {
      blocks.removeWhere((Block item) => item.seriesId == block.seriesId);
    } else {
      blocks.removeWhere((Block item) => item.id == blockId);
    }
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
  }

  void deleteBlocks(Set<int> ids, {bool wholeSeries = false}) {
    if (ids.isEmpty) return;
    final List<Block> selected = blocks
        .where((Block block) => ids.contains(block.id))
        .toList(growable: false);
    if (selected.isEmpty) return;
    final Set<int> seriesIds = wholeSeries
        ? selected.map((Block block) => block.seriesId).whereType<int>().toSet()
        : <int>{};
    _pushUndo(
      selected.length == 1
          ? 'Deleted ${selected.first.title}'
          : 'Deleted ${selected.length} blocks',
    );
    blocks.removeWhere(
      (Block block) =>
          ids.contains(block.id) ||
          (block.seriesId != null && seriesIds.contains(block.seriesId)),
    );
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
  }

  /// Merges selected blocks into one block spanning the earliest start to the
  /// latest end. The earliest block supplies the category, colour and alarm
  /// settings. [joinTitles] keeps every distinct title instead of just the
  /// earliest one.
  Block? combineBlocks(Set<int> ids, {bool joinTitles = false}) {
    final List<Block> chosen =
        blocks
            .where((Block block) => ids.contains(block.id))
            .toList(growable: false)
          ..sort((Block a, Block b) => a.start.compareTo(b.start));
    if (chosen.length < 2) return null;

    final Block first = chosen.first;
    DateTime start = chosen.first.start;
    DateTime end = chosen.first.end;
    for (final Block block in chosen) {
      if (block.start.isBefore(start)) start = block.start;
      if (block.end.isAfter(end)) end = block.end;
    }
    if (!end.isAfter(start)) return null;

    final String title = joinTitles ? _joinedTitle(chosen) : first.title;
    final Block combined = first.copyWith(
      title: title,
      start: start,
      end: end,
      repeat: RepeatSpec.none,
      clearSeriesId: true,
      lane: first.lane,
    );

    _pushUndo('Combined ${chosen.length} blocks into “${combined.title}”');
    blocks.removeWhere((Block block) => ids.contains(block.id));
    blocks.add(combined);
    _sortBlocks();
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
    return combined;
  }

  String _joinedTitle(List<Block> chosen) {
    final List<String> titles = <String>[];
    for (final Block block in chosen) {
      final String title = block.title.trim();
      if (title.isEmpty || title == 'Untitled') continue;
      if (!titles.contains(title)) titles.add(title);
    }
    if (titles.isEmpty) return chosen.first.title;
    final String joined = titles.join(' + ');
    return joined.length <= 80 ? joined : '${joined.substring(0, 79)}…';
  }

  void batchEditBlocks(
    Set<int> ids, {
    String? trackId,
    String? title,
    BlockKind? kind,
    Set<AlarmOffset>? alarms,
    RepeatSpec? repeat,
    int durationDeltaMinutes = 0,
  }) {
    if (ids.isEmpty) return;
    final List<Block> selected = blocks
        .where((Block block) => ids.contains(block.id))
        .toList(growable: false);
    if (selected.isEmpty) return;
    _pushUndo(
      selected.length == 1
          ? 'Edited ${selected.first.title}'
          : 'Edited ${selected.length} blocks',
    );

    final Map<int, List<Block>> groups = <int, List<Block>>{};
    for (final Block block in selected) {
      final int key = block.seriesId ?? block.id;
      groups.putIfAbsent(key, () => <Block>[]).add(block);
    }
    for (final MapEntry<int, List<Block>> entry in groups.entries) {
      final List<Block> group = entry.value
        ..sort((Block a, Block b) => a.start.compareTo(b.start));
      final Block base = group.first;
      final int? seriesId = base.seriesId;
      final List<Block> affected = seriesId == null
          ? <Block>[base]
          : blocks
                .where((Block block) => block.seriesId == seriesId)
                .toList(growable: false);
      final int primaryId = base.id;
      final Duration duration = base.duration;
      int minutes = duration.inMinutes + durationDeltaMinutes;
      if (minutes < 5) minutes = 5;
      final String? nextTitle = title?.trim();
      final Block draft = base.copyWith(
        id: primaryId,
        trackId: trackId ?? base.trackId,
        title: nextTitle == null || nextTitle.isEmpty ? null : nextTitle,
        kind: kind ?? base.kind,
        alarms: alarms ?? base.alarms,
        repeat: repeat ?? base.repeat,
        end: base.start.add(Duration(minutes: minutes)),
        seriesId: seriesId,
        clearSeriesId: repeat != null && !repeat.active || seriesId == null,
        lane: trackId != null || kind != null ? null : base.lane,
        clearLane: trackId != null || kind != null,
      );
      blocks.removeWhere((Block block) => affected.contains(block));
      if (!draft.repeat.active || !draft.repeat.isValid) {
        blocks.add(draft.copyWith(seriesId: null, clearSeriesId: true));
      } else {
        final int newSeriesId = seriesId ?? primaryId;
        final List<Block> generated = _expandRecurringBlock(
          draft.copyWith(seriesId: newSeriesId),
          newSeriesId,
        );
        blocks.addAll(generated);
      }
    }
    _sortBlocks();
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
  }

  void addTemplateFromBlock(Block block) {
    addTemplateFromBlocks(<Block>[block]);
  }

  void addTemplateFromBlocks(Iterable<Block> selection) {
    final List<Block> chosen = selection.toList(growable: false);
    if (chosen.isEmpty) return;
    chosen.sort((Block a, Block b) => a.start.compareTo(b.start));
    final DateTime anchor = chosen.first.start;
    final int span = chosen
        .map((Block block) => block.end.difference(anchor).inMinutes)
        .reduce(math.max);
    final List<TemplatePart> parts = <TemplatePart>[
      for (final Block block in chosen)
        TemplatePart(
          title: block.title.trim().isEmpty ? 'Untitled' : block.title.trim(),
          trackId: block.trackId,
          offsetMinutes: block.start.difference(anchor).inMinutes,
          durationMinutes: math.max(1, block.duration.inMinutes),
          kind: block.kind,
          alarms: block.alarms,
          repeat: block.repeat,
        ),
    ];
    final Block first = chosen.first;
    final Template template = Template(
      id: _nextTemplateId++,
      title: chosen.length == 1
          ? (first.title.trim().isEmpty ? 'Untitled' : first.title.trim())
          : '${chosen.length}-block selection',
      trackId: first.trackId,
      durationMinutes: chosen.length == 1
          ? math.max(1, first.duration.inMinutes)
          : math.max(1, span),
      kind: first.kind,
      alarms: first.alarms,
      repeat: first.repeat,
      parts: parts,
    );
    templates.add(template);
    notifyListeners();
    _scheduleSave();
  }

  void deleteTemplate(int id) {
    templates.removeWhere((Template template) => template.id == id);
    notifyListeners();
    _scheduleSave();
  }

  void addTemplate(Template template) {
    templates.add(
      Template(
        id: _nextTemplateId++,
        title: template.title,
        trackId: template.trackId,
        durationMinutes: template.durationMinutes,
        kind: template.kind,
        alarms: template.alarms,
        repeat: template.repeat,
        parts: List<TemplatePart>.of(template.parts),
      ),
    );
    notifyListeners();
    _scheduleSave();
  }

  List<Block> addBlocksFromTemplate(Template template, DateTime start) {
    final List<TemplatePart> parts = template.parts.isEmpty
        ? <TemplatePart>[
            TemplatePart(
              title: template.title,
              trackId: template.trackId,
              offsetMinutes: 0,
              durationMinutes: template.durationMinutes,
              kind: template.kind,
              alarms: template.alarms,
              repeat: template.repeat,
            ),
          ]
        : template.parts;
    if (parts.isEmpty) return const <Block>[];
    _pushUndo('Added ${template.title}');
    final List<Block> added = <Block>[];
    for (final TemplatePart part in parts) {
      final DateTime partStart = start.add(
        Duration(minutes: math.max(0, part.offsetMinutes)),
      );
      final DateTime partEnd = partStart.add(
        Duration(minutes: math.max(1, part.durationMinutes)),
      );
      final int id = _nextBlockId++;
      final Block draft = Block(
        id: id,
        trackId: part.trackId,
        title: part.title,
        start: partStart,
        end: partEnd,
        kind: part.kind,
        alarms: part.alarms,
        repeat: part.repeat,
      );
      if (!part.repeat.active || !part.repeat.isValid) {
        blocks.add(draft);
        added.add(draft);
      } else {
        final int seriesId = id;
        final List<Block> generated = _expandRecurringBlock(
          draft.copyWith(seriesId: seriesId),
          seriesId,
        );
        blocks.addAll(generated);
        added.addAll(generated);
      }
    }
    _sortBlocks();
    _ensureUncategorized();
    notifyListeners();
    _scheduleSave();
    return added;
  }

  Map<String, dynamic> toJsonMap() => <String, dynamic>{
    'format': 'timeline-sync-v1',
    'app': 'Timeline',
    'exportedAt': DateTime.now().toUtc().toIso8601String(),
    'tracks': tracks.map((Track track) => track.toJson()).toList(),
    'blocks': blocks.map((Block block) => block.toJson()).toList(),
    'templates': templates
        .map((Template template) => template.toJson())
        .toList(),
    'trackOpen': Map<String, bool>.from(trackOpen),
    'namesHidden': !showNames,
    'locked': locked,
    'uncategorizedSlot': _uncategorizedSlot,
    'sample': _sampleVersion,
  };

  String exportJsonString({bool pretty = true}) {
    if (pretty) {
      return const JsonEncoder.withIndent('  ').convert(toJsonMap());
    }
    return jsonEncode(toJsonMap());
  }

  ImportResult importJsonString(String raw) {
    final Object? decoded;
    try {
      decoded = jsonDecode(raw);
    } catch (_) {
      throw const FormatException('That file is not valid JSON.');
    }
    if (decoded is! Map) {
      throw const FormatException('Not a Timeline sync file.');
    }
    final Map<String, dynamic> map = Map<String, dynamic>.from(decoded);
    final Object? rawTracks = map['tracks'];
    final Object? rawBlocks = map['blocks'];
    if (rawTracks is! List || rawBlocks is! List) {
      throw const FormatException('Not a Timeline sync file.');
    }

    final UndoState before = captureState();
    final List<Track> nextTracks = <Track>[];
    final Set<String> trackIds = <String>{};
    for (final Object? item in rawTracks) {
      if (item is! Map) continue;
      final Track track = Track.fromJson(Map<String, dynamic>.from(item));
      if (track.id.isEmpty || track.id == _uncatId || !trackIds.add(track.id)) {
        continue;
      }
      nextTracks.add(track);
    }

    final List<Block> nextBlocks = <Block>[];
    final Set<int> blockIds = <int>{};
    int nextBlockId = 1;
    for (final Object? item in rawBlocks) {
      if (item is! Map) continue;
      try {
        final Map<String, dynamic> json = Map<String, dynamic>.from(item);
        int id = (json['id'] is num)
            ? (json['id'] as num).toInt()
            : int.tryParse('${json['id'] ?? ''}') ?? 0;
        if (id <= 0 || blockIds.contains(id)) {
          while (blockIds.contains(nextBlockId)) {
            nextBlockId++;
          }
          id = nextBlockId;
        }
        blockIds.add(id);
        nextBlockId = math.max(nextBlockId, id + 1);
        final Block block = Block.fromJson(json, fallbackId: id);
        block.id = id;
        if (!trackIds.contains(block.trackId)) block.trackId = _uncatId;
        nextBlocks.add(block);
      } catch (_) {
        // Ignore individually invalid blocks.
      }
    }

    final List<Template> nextTemplates = <Template>[];
    int nextTemplateId = 1;
    final Object? rawTemplates = map['templates'];
    if (rawTemplates is List) {
      for (final Object? item in rawTemplates) {
        if (item is! Map) continue;
        try {
          final Map<String, dynamic> json = Map<String, dynamic>.from(item);
          int id = (json['id'] is num)
              ? (json['id'] as num).toInt()
              : int.tryParse('${json['id'] ?? ''}') ?? 0;
          if (id <= 0) id = nextTemplateId++;
          nextTemplateId = math.max(nextTemplateId, id + 1);
          nextTemplates.add(Template.fromJson(json, fallbackId: id));
        } catch (_) {}
      }
    }

    tracks
      ..clear()
      ..addAll(nextTracks);
    blocks
      ..clear()
      ..addAll(nextBlocks);
    templates
      ..clear()
      ..addAll(nextTemplates);
    _nextBlockId = nextBlockId;
    _nextTrackId = _nextAvailableTrackNumber();
    _nextTemplateId = math.max(nextTemplateId, _maxTemplateId() + 1);
    trackOpen.clear();
    final Object? rawOpen = map['trackOpen'];
    if (rawOpen is Map) {
      rawOpen.forEach((Object? key, Object? value) {
        if (key is String) trackOpen[key] = value != false;
      });
    }
    for (final Track track in tracks) {
      trackOpen.putIfAbsent(track.id, () => true);
    }
    if (map.containsKey('namesHidden')) showNames = map['namesHidden'] != true;
    if (map.containsKey('locked')) locked = map['locked'] == true;
    _uncategorizedSlot = map['uncategorizedSlot'] is num
        ? (map['uncategorizedSlot'] as num).toInt()
        : -1;
    _sampleVersion = _sampleDataVersion;
    _ensureUncategorized();
    undoStack.add(UndoEntry(state: before, label: 'Imported sync file'));
    if (undoStack.length > maxUndo) undoStack.removeAt(0);
    notifyListeners();
    _scheduleSave();
    return ImportResult(tracks: tracks.length, blocks: blocks.length);
  }

  Future<void> flush() async {
    _saveTimer?.cancel();
    _saveTimer = null;
    final TimelineStorage storage = _storage ??=
        await createDefaultTimelineStorage();
    await storage.write(
      jsonEncode(<String, dynamic>{
        'tracks': tracks.map((Track track) => track.toJson()).toList(),
        'blocks': blocks.map((Block block) => block.toJson()).toList(),
        'templates': templates
            .map((Template template) => template.toJson())
            .toList(),
        'trackOpen': Map<String, bool>.from(trackOpen),
        'namesHidden': !showNames,
        'locked': locked,
        'uncategorizedSlot': _uncategorizedSlot,
        'sample': _sampleVersion,
      }),
    );
  }

  void _scheduleSave() {
    _saveTimer?.cancel();
    _saveTimer = Timer(const Duration(milliseconds: 350), () {
      _saveTimer = null;
      unawaited(flush());
    });
  }

  void _seedSampleData() {
    tracks
      ..clear()
      ..addAll(
        _sampleTracks.entries.map(
          (MapEntry<String, ({String name, int color})> entry) => Track(
            id: entry.key,
            name: entry.value.name,
            colorValue: entry.value.color,
          ),
        ),
      );
    blocks.clear();
    templates.clear();
    trackOpen.clear();
    for (final Track track in tracks) {
      trackOpen[track.id] = true;
    }
    _nextBlockId = 1;
    _nextTrackId = 1;
    _nextTemplateId = 1;
    _uncategorizedSlot = -1;
    _sampleVersion = _sampleDataVersion;

    final DateTime now = DateTime.now();
    final DateTime today = startOfLocalDay(now);

    for (int dayOffset = -5; dayOffset <= 4; dayOffset++) {
      final DateTime base = DateTime(
        today.year,
        today.month,
        today.day + dayOffset,
      );
      final int weekday = base.weekday;
      final _Rng rng = _Rng(9000 + dayOffset.abs() * 137 + 11);
      int jitter(int minutes) => ((rng.next() * 2 - 1) * minutes).round();

      DateTime local(double hour) {
        final int h = hour.floor();
        final int m = ((hour - h) * 60).round();
        return atLocalTime(base, h, m);
      }

      final DateTime breakfast = local(8).add(Duration(minutes: jitter(22)));
      final DateTime lunch = local(13).add(Duration(minutes: jitter(28)));
      final DateTime dinner = local(19.5).add(Duration(minutes: jitter(30)));

      _sampleBlock(
        'food',
        'Breakfast',
        breakfast,
        breakfast.add(const Duration(minutes: 25)),
      );
      _sampleBlock(
        'food',
        'Lunch',
        lunch,
        lunch.add(const Duration(minutes: 35)),
      );
      _sampleBlock(
        'food',
        'Dinner',
        dinner,
        dinner.add(const Duration(minutes: 45)),
      );
      _sampleBlock(
        'food',
        'Digestion',
        breakfast,
        breakfast.add(const Duration(hours: 12)),
        BlockKind.zone,
      );

      if (weekday >= DateTime.monday && weekday <= DateTime.friday) {
        _sampleBlock('work', 'Deep work', local(9.5), local(12.5));
        _sampleBlock('work', 'Admin', local(14), local(19));
      } else {
        _sampleBlock('work', 'Side project', local(11), local(13));
      }

      if (rng.next() > 0.3) {
        _sampleBlock('personal', 'Walk', local(18), local(18.75));
      }
      if (rng.next() > 0.55) {
        _sampleBlock('personal', 'Chores', local(17), local(17.5));
      }
      _sampleBlock('learning', 'Reading', local(20), local(20.75));
      if (rng.next() > 0.45) {
        _sampleBlock('health', 'Medication', local(21), local(21.08));
      }
      _sampleBlock('media', 'Wind down', local(21.5), local(22.5));
      _sampleBlock(
        'rest',
        'Sleep',
        local(23.5),
        local(23.5).add(const Duration(hours: 8)),
        BlockKind.zone,
      );
    }

    _sampleBlock(
      'health',
      'Dentist',
      atLocalTime(addLocalDays(today, 1), 11, 0),
      atLocalTime(addLocalDays(today, 1), 12, 0),
    );
    _sampleBlock(
      'personal',
      'Call family',
      atLocalTime(today, 19, 15),
      atLocalTime(today, 19, 45),
    );

    templates.addAll(<Template>[
      Template(
        id: _nextTemplateId++,
        title: 'Deep work',
        trackId: 'work',
        durationMinutes: 180,
      ),
      Template(
        id: _nextTemplateId++,
        title: 'Walk',
        trackId: 'personal',
        durationMinutes: 45,
      ),
      Template(
        id: _nextTemplateId++,
        title: 'Focus',
        trackId: 'learning',
        durationMinutes: 90,
      ),
    ]);
  }

  void _sampleBlock(
    String trackId,
    String title,
    DateTime start,
    DateTime end, [
    BlockKind kind = BlockKind.event,
  ]) {
    blocks.add(
      Block(
        id: _nextBlockId++,
        trackId: trackId,
        title: title,
        start: start,
        end: end,
        kind: kind,
      ),
    );
  }

  @override
  void dispose() {
    _saveTimer?.cancel();
    _saveTimer = null;
    super.dispose();
  }
}

class _MoveOriginals {
  const _MoveOriginals({
    required this.start,
    required this.end,
    required this.lane,
  });

  final DateTime start;
  final DateTime end;
  final int lane;
}

class _Rng {
  _Rng(this._state);

  int _state;

  double next() {
    _state = (_state + 0x6D2B79F5) & 0x7FFFFFFF;
    int t = _state;
    t = (t ^ (t >> 15)) * (t | 1) & 0x7FFFFFFF;
    t ^= t + ((t ^ (t >> 7)) * (t | 61) & 0x7FFFFFFF);
    return ((t ^ (t >> 14)) & 0x7FFFFFFF) / 0x80000000;
  }
}
